#pragma once
#define IDI_APP      101
#define IDI_APP_OPEN 102

// Animated "scanning" frames, four per style, generated by
// scripts/make-scan-icons.py.  IDI_APP_SCAN_* is the folded-plate tray style,
// IDI_APP_OPEN_SCAN_* the transparent taskbar style.
#define IDI_APP_SCAN_0      110
#define IDI_APP_SCAN_1      111
#define IDI_APP_SCAN_2      112
#define IDI_APP_SCAN_3      113
#define IDI_APP_OPEN_SCAN_0 120
#define IDI_APP_OPEN_SCAN_1 121
#define IDI_APP_OPEN_SCAN_2 122
#define IDI_APP_OPEN_SCAN_3 123

// Ring badge for ITaskbarList3::SetOverlayIcon. This is the channel that
// actually reaches the Windows 11 taskbar button: WM_SETICON only updates the
// window icon there, not the glommed button icon.
#define IDI_SCAN_OVERLAY_0 130
#define IDI_SCAN_OVERLAY_1 131
#define IDI_SCAN_OVERLAY_2 132
#define IDI_SCAN_OVERLAY_3 133

#define IDR_MANIFEST 1
